        rawValue = table?["{arg0}_ascii"] ?? table?[idName] ?? zero;
        break;
      default: // leastStrict / lengthOnly
        return zero;
    }

    if (rawValue is String) {
      return rawValue.codeUnits;
    } else if (rawValue is List<int>) {
      return rawValue;
    } else {
      return zero;
    }
  }

